113	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
114	    @Override
115	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
116	        HttpHeaders headers = new HttpHeaders();
117	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
118	        owner.setTelephone(normalizeTelephone(owner.getTelephone()));
119	        if (ownerAlreadyExists(owner) || emailAlreadyExists(owner)) {
120	            return new ResponseEntity<>(HttpStatus.CONFLICT);
121	        }
122	        if (dailyRegistrationLimitReached()) {
123	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
124	        }
125	        if (cityAtCapacity(owner.getCity())) {
126	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
127	        }
128	        if (owner.getRegistrationDate() == null) {
129	            owner.setRegistrationDate(LocalDate.now());
130	        }
131	        owner.setCity(resolveCity(owner.getCity()));
132	        int membershipNumber = this.clinicService.findAllOwners().size() + 1;
133	        owner.setMembershipNumber(membershipNumber);
134	        owner.setCustomerCode(nextCustomerCode(owner.getCity()));
135	        owner.setMembershipTier(membershipTierFor(membershipNumber));
136	        owner.setNamesakeCount(namesakeCount(owner.getLastName()));
137	        owner.setSharesHousehold(sharesHousehold(owner));
138	        owner.setLocality(localityFor(owner.getCity()));
139	        this.clinicService.saveOwner(owner);
140	        AUDIT.info("owner created: user={} ownerId={} membershipNumber={}",
141	            currentUsername(), owner.getId(), owner.getMembershipNumber());
142	        warnIfPossibleBulkSignup(owner);
143	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
144	        headers.setLocation(UriComponentsBuilder.newInstance()
145	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
146	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
147	    }
