149	    /**
150	     * Resolves the name of the currently authenticated user for audit logging, falling back to
151	     * {@code "anonymous"} when no authentication is present in the security context.
152	     *
153	     * @return the authenticated user's name, or {@code "anonymous"} if unauthenticated
154	     */
155	    private static String currentUsername() {
156	        Authentication authentication = SecurityContextHolder.getContext().getAuthentication();
157	        return authentication != null ? authentication.getName() : "anonymous";
158	    }
