160	    /**
161	     * The number of existing owners that must already share a newly created owner's telephone area
162	     * code (see {@link #areaCode(String)}) before a possible-bulk-signup warning is emitted.
163	     */
164	    private static final long BULK_SIGNUP_AREA_CODE_THRESHOLD = 5;
165	
166	    /**
167	     * Emits a WARN to the {@link #AUDIT} logger flagging a possible bulk signup when the newly
168	     * created owner's telephone shares its area code (first three digits, see
169	     * {@link #areaCode(String)}) with {@value #BULK_SIGNUP_AREA_CODE_THRESHOLD} or more existing
170	     * owners. The owner itself is excluded from the count so only previously stored owners are
171	     * considered. Owners without a resolvable area code are ignored.
172	     *
173	     * @param owner the owner that has just been created and stored
174	     */
175	    private void warnIfPossibleBulkSignup(Owner owner) {
176	        String areaCode = areaCode(owner.getTelephone());
177	        if (areaCode == null) {
178	            return;
179	        }
180	        long existingWithAreaCode = this.clinicService.findAllOwners().stream()
181	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
182	            .filter(existing -> areaCode.equals(areaCode(existing.getTelephone())))
183	            .count();
184	        if (existingWithAreaCode >= BULK_SIGNUP_AREA_CODE_THRESHOLD) {
185	            AUDIT.warn("possible bulk signup: user={} ownerId={} areaCode={} existingOwners={}",
186	                currentUsername(), owner.getId(), areaCode, existingWithAreaCode);
187	        }
188	    }
