190	    /**
191	     * Resolves the area code of a telephone number, defined as the first three digits of its
192	     * normalized digits-only form (see {@link #normalizeTelephone(String)}).
193	     *
194	     * @param telephone the raw telephone value, may be {@code null}
195	     * @return the three-digit area code, or {@code null} if fewer than three digits are present
196	     */
197	    private static String areaCode(String telephone) {
198	        String normalized = normalizeTelephone(telephone);
199	        if (normalized == null || normalized.length() < 3) {
200	            return null;
201	        }
202	        return normalized.substring(0, 3);
203	    }
