205	    /**
206	     * The maximum number of owners that may be registered on any single day (by registration date).
207	     */
208	    private static final long MAX_OWNERS_PER_DAY = 20;
209	
210	    /**
211	     * Determines whether the maximum number of owners for the current day has already been reached.
212	     * Owners are counted by their registration date, so once {@value #MAX_OWNERS_PER_DAY} owners
213	     * carry today's registration date no further owners may be created today.
214	     *
215	     * @return {@code true} if today's registration limit has been reached
216	     */
217	    private boolean dailyRegistrationLimitReached() {
218	        LocalDate today = LocalDate.now();
219	        long registeredToday = this.clinicService.findAllOwners().stream()
220	            .filter(existing -> today.equals(existing.getRegistrationDate()))
221	            .count();
222	        return registeredToday >= MAX_OWNERS_PER_DAY;
223	    }
224	
225	    /**
226	     * The maximum number of owners that may be registered in any single city.
227	     */
228	    private static final long MAX_OWNERS_PER_CITY = 8;
229	
230	    /**
231	     * Determines whether the given city has already reached its capacity of
232	     * {@value #MAX_OWNERS_PER_CITY} owners. Owners are counted per city ignoring letter case, so
233	     * once a city holds {@value #MAX_OWNERS_PER_CITY} owners no further owners may be created there.
234	     *
235	     * @param city the raw city supplied for the owner being created, may be {@code null}
236	     * @return {@code true} if the city already contains the maximum number of owners
237	     */
238	    private boolean cityAtCapacity(String city) {
239	        if (city == null) {
240	            return false;
241	        }
242	        long ownersInCity = this.clinicService.findAllOwners().stream()
243	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
244	            .count();
245	        return ownersInCity >= MAX_OWNERS_PER_CITY;
246	    }
247	
248	    /**
249	     * Resolves the city to store for a newly created owner. If another owner is already stored in
250	     * the same city (compared ignoring letter case), that existing owner's exact spelling of the
251	     * city name is reused so that a single city is always represented consistently. Otherwise the
252	     * supplied city is title-cased (see {@link #titleCase(String)}) before being stored.
253	     *
254	     * @param city the raw city supplied for the owner being created, may be {@code null}
255	     * @return the city to store, or {@code null} if {@code city} is {@code null}
256	     */
257	    private String resolveCity(String city) {
258	        if (city == null) {
259	            return null;
260	        }
261	        return this.clinicService.findAllOwners().stream()
262	            .map(Owner::getCity)
263	            .filter(existing -> existing != null && existing.equalsIgnoreCase(city))
264	            .findFirst()
265	            .orElseGet(() -> titleCase(city));
266	    }
267	
268	    /**
269	     * Title-cases a value so that the first letter of every whitespace-separated word is
270	     * upper-cased and every other letter is lower-cased, preserving the original whitespace. For
271	     * example {@code "new  york"} becomes {@code "New  York"} and {@code "LONDON"} becomes
272	     * {@code "London"}.
273	     *
274	     * @param value the raw value, may be {@code null}
275	     * @return the title-cased value, or {@code null} if {@code value} is {@code null}
276	     */
277	    private static String titleCase(String value) {
278	        if (value == null) {
279	            return null;
280	        }
281	        StringBuilder result = new StringBuilder(value.length());
282	        boolean startOfWord = true;
283	        for (int i = 0; i < value.length(); i++) {
284	            char c = value.charAt(i);
285	            if (Character.isWhitespace(c)) {
286	                startOfWord = true;
287	                result.append(c);
288	            } else {
289	                result.append(startOfWord ? Character.toUpperCase(c) : Character.toLowerCase(c));
290	                startOfWord = false;
291	            }
292	        }
293	        return result.toString();
294	    }
