296	    /**
297	     * Builds the customer code for a newly created owner in the given city, formatted as
298	     * {@code <UPPERCASE_CITY>-<NNNN>} where {@code NNNN} is one more than the number of owners
299	     * already stored in that city, zero-padded to four digits (e.g. {@code LONDON-0007}). The
300	     * count of existing owners in the city ignores letter case.
301	     *
302	     * @param city the city of the owner being created
303	     * @return the assigned customer code
304	     */
305	    private String nextCustomerCode(String city) {
306	        long ownersInCity = this.clinicService.findAllOwners().stream()
307	            .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
308	            .count();
309	        return String.format("%s-%04d", city.toUpperCase(), ownersInCity + 1);
310	    }
