312	    /**
313	     * The maximum membership number that still qualifies an owner for the founding tier. The
314	     * first {@value #MAX_FOUNDING_MEMBERS} owners ever created are founding members.
315	     */
316	    private static final int MAX_FOUNDING_MEMBERS = 100;
317	
318	    /**
319	     * Resolves the membership tier for a newly created owner from its sequential membership
320	     * number. The first {@value #MAX_FOUNDING_MEMBERS} owners ever created are {@code FOUNDING};
321	     * every later owner is {@code STANDARD}.
322	     *
323	     * @param membershipNumber the owner's sequential membership number
324	     * @return {@code "FOUNDING"} or {@code "STANDARD"}
325	     */
326	    private static String membershipTierFor(int membershipNumber) {
327	        return membershipNumber <= MAX_FOUNDING_MEMBERS ? "FOUNDING" : "STANDARD";
328	    }
329	
330	    /**
331	     * Counts how many existing owners already share the given last name, ignoring letter case and
332	     * surrounding or repeated whitespace. This is evaluated at the moment a new owner is created,
333	     * before that owner is stored, so it reflects the number of other owners that carry the same
334	     * last name.
335	     *
336	     * @param lastName the last name of the owner being created, may be {@code null}
337	     * @return the number of other owners already sharing that last name
338	     */
339	    private int namesakeCount(String lastName) {
340	        String normalized = normalize(lastName);
341	        return (int) this.clinicService.findAllOwners().stream()
342	            .filter(existing -> Objects.equals(normalize(existing.getLastName()), normalized))
343	            .count();
344	    }
345	
346	    /**
347	     * Determines whether another owner already shares a household with the owner being created,
348	     * meaning an existing owner already has the same address and city. Both address and city are
349	     * compared ignoring letter case and surrounding or repeated whitespace (see
350	     * {@link #normalize(String)}). This is evaluated before the new owner is stored, so it reflects
351	     * only owners that already existed.
352	     *
353	     * @param owner the candidate owner to check
354	     * @return {@code true} if a stored owner already has the same address and city
355	     */
356	    private boolean sharesHousehold(Owner owner) {
357	        String address = normalize(owner.getAddress());
358	        String city = normalize(owner.getCity());
359	        return this.clinicService.findAllOwners().stream()
360	            .anyMatch(existing -> Objects.equals(normalize(existing.getAddress()), address)
361	                && Objects.equals(normalize(existing.getCity()), city));
362	    }
363	
364	    /**
365	     * The locality assigned to an owner whose city is the single most common city among the
366	     * existing owners at the moment of creation.
367	     */
368	    private static final String LOCALITY_LOCAL = "local";
369	
370	    /**
371	     * The locality assigned to an owner whose city is not the single most common city among the
372	     * existing owners at the moment of creation.
373	     */
374	    private static final String LOCALITY_REMOTE = "remote";
375	
376	    /**
377	     * Resolves the locality for a newly created owner. The owner is {@code "local"} when their city
378	     * is the single most common city among the owners that already exist (compared ignoring letter
379	     * case and surrounding or repeated whitespace, see {@link #normalize(String)}); otherwise they
380	     * are {@code "remote"}. If there is no existing owner, or the most common city is shared by a
381	     * tie, or the owner's city is not that single most common city, the owner is {@code "remote"}.
382	     * This is evaluated before the new owner is stored, so it reflects only owners that already
383	     * existed.
384	     *
385	     * @param city the city of the owner being created, may be {@code null}
386	     * @return {@code "local"} or {@code "remote"}
387	     */
388	    private String localityFor(String city) {
389	        if (city == null) {
390	            return LOCALITY_REMOTE;
391	        }
392	        Map<String, Long> countsByCity = this.clinicService.findAllOwners().stream()
393	            .map(Owner::getCity)
394	            .filter(Objects::nonNull)
395	            .collect(Collectors.groupingBy(OwnerRestControllerV1::normalize, Collectors.counting()));
396	        if (countsByCity.isEmpty()) {
397	            return LOCALITY_REMOTE;
398	        }
399	        long max = Collections.max(countsByCity.values());
400	        List<String> mostCommon = countsByCity.entrySet().stream()
401	            .filter(entry -> entry.getValue() == max)
402	            .map(Map.Entry::getKey)
403	            .toList();
404	        if (mostCommon.size() != 1) {
405	            return LOCALITY_REMOTE;
406	        }
407	        return mostCommon.get(0).equals(normalize(city)) ? LOCALITY_LOCAL : LOCALITY_REMOTE;
408	    }
