410	    /**
411	     * Determines whether an owner already exists using the same telephone number.
412	     * Comparison ignores letter case and surrounding or repeated whitespace.
413	     *
414	     * @param owner the candidate owner to check
415	     * @return {@code true} if any other owner with the same telephone is already stored
416	     */
417	    private boolean ownerAlreadyExists(Owner owner) {
418	        String telephone = normalizeTelephone(owner.getTelephone());
419	        return this.clinicService.findAllOwners().stream()
420	            .anyMatch(existing -> Objects.equals(normalizeTelephone(existing.getTelephone()), telephone));
421	    }
422	
423	    /**
424	     * Normalizes a telephone number to digits only, stripping spaces, dashes and
425	     * parentheses (any non-digit character). This is the canonical stored form and is
426	     * used for the telephone-uniqueness check, so {@code "(613) 555-0100"} and
427	     * {@code "6135550100"} are treated as the same number.
428	     *
429	     * @param telephone the raw telephone value, may be {@code null}
430	     * @return the digits-only value, or {@code null} if {@code telephone} is {@code null}
431	     */
432	    private static String normalizeTelephone(String telephone) {
433	        if (telephone == null) {
434	            return null;
435	        }
436	        return telephone.replaceAll("[^0-9]", "");
437	    }
438	
439	    /**
440	     * Determines whether another owner already uses the same email address.
441	     * Owners without an email are ignored, so a missing email never conflicts.
442	     * Comparison ignores letter case and surrounding or repeated whitespace.
443	     *
444	     * @param owner the candidate owner to check
445	     * @return {@code true} if the candidate supplies an email already used by a stored owner
446	     */
447	    private boolean emailAlreadyExists(Owner owner) {
448	        String email = normalize(owner.getEmail());
449	        if (email == null || email.isEmpty()) {
450	            return false;
451	        }
452	        return this.clinicService.findAllOwners().stream()
453	            .anyMatch(existing -> Objects.equals(normalize(existing.getEmail()), email));
454	    }
455	
456	    /**
457	     * Normalizes a value for duplicate detection so that comparisons ignore letter
458	     * case and surrounding or repeated whitespace. Leading and trailing whitespace is
459	     * trimmed, any run of internal whitespace is collapsed to a single space, and the
460	     * result is lower-cased. For example {@code "  john   smith "} and {@code "John Smith"}
461	     * both normalize to {@code "john smith"}.
462	     *
463	     * @param value the raw value, may be {@code null}
464	     * @return the normalized value, or {@code null} if {@code value} is {@code null}
465	     */
466	    private static String normalize(String value) {
467	        if (value == null) {
468	            return null;
469	        }
470	        return value.strip().replaceAll("\\s+", " ").toLowerCase();
471	    }
