524	        if (currentOwner != null) {
525	            Pet currentPet = this.clinicService.findPetById(petId);
526	            if (currentPet != null) {
527	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
528	                currentPet.setName(petFieldsDto.getName());
529	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
530	                this.clinicService.savePet(currentPet);
531	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
532	            }
533	        }
534	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
535	    }
